    gpu_free_kernel(ctx, ctx->program->mainzisegred_large_11409);
    gpu_free_kernel(ctx, ctx->program->mainzisegred_large_11431);
    gpu_free_kernel(ctx, ctx->program->mainzisegred_large_11600);
