struct futhark_f32_3d {
    struct memblock_device mem;
    int64_t shape[3];
};
struct futhark_f32_3d *futhark_new_f32_3d(struct futhark_context *ctx, const float *data, int64_t dim0, int64_t dim1, int64_t dim2)
{
    int err = 0;
    struct futhark_f32_3d *bad = NULL;
    struct futhark_f32_3d *arr = (struct futhark_f32_3d *) malloc(sizeof(struct futhark_f32_3d));
    
    if (arr == NULL)
        return bad;
    lock_lock(&ctx->lock);
    CUDA_SUCCEED_FATAL(cuCtxPushCurrent(ctx->cu_ctx));
    arr->mem.references = NULL;
    arr->shape[0] = dim0;
    arr->shape[1] = dim1;
    arr->shape[2] = dim2;
    if (memblock_alloc_device(ctx, &arr->mem, arr->shape[0] * arr->shape[1] * arr->shape[2] * 4, "arr->mem"))
        err = 1;
    err = memcpy_host2gpu(ctx, NULL, false, arr->mem.mem, 0, (const unsigned char *) data, 0, (size_t) (dim0 * dim1 * dim2) * 4);
    CUDA_SUCCEED_FATAL(cuCtxPopCurrent(&ctx->cu_ctx));
    lock_unlock(&ctx->lock);
    if (err != 0) {
        free(arr);
        return bad;
    }
    return arr;
}
